functions.body:
block([mat:matrix([]),d1:length(sp1), ans:[]],
for v in sp1 do mat:addcol(mat,v), for v in sp2 do mat:addcol(mat,v),
nullB: nullspace(mat),
for v in nullB do ans:cons(sum(v[i][1]*sp1[i],i,1,d1),ans),ans)

block([mat:matrix([]), ans:[]],
for v in sp1 do mat:addcol(mat,v), for v in sp2 do mat:addcol(mat,v),
ans:args(columnspace(mat)),ans)

prts.feedbackvariables:
validInput: collistp(ans2);
ans: if validInput then ans2 else []; /*avoid errors due to invalid input*/
independent: not dependentvects(ans);
subspaceR: inSpan(rowsascols,ans);
subspaceC: inSpan(cols,ans);
spanning: is(subspaceR and subspaceC and rank(matrify(ans))=dimintersectionrc);

validInput: collistp(ans3);
ans: if validInput then ans3 else []; /*avoid errors due to invalid input*/
independent: not dependentvects(ans);
spanning: is(rank(matrify(ans))=dimplusrc);
